import{_ as t,c as a,o as r,aj as l}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"Brioche (Early Butter, Cold Ferment)","description":"Rich, soft brioche using early butter incorporation and an overnight cold ferment for structure and flavor.","frontmatter":{"title":"Brioche (Early Butter, Cold Ferment)","description":"Rich, soft brioche using early butter incorporation and an overnight cold ferment for structure and flavor.","head":[["meta",{"name":"description","content":"Rich, soft brioche using early butter incorporation and an overnight cold ferment for structure and flavor."}],["meta",{"property":"og:title","content":"Brioche (Early Butter, Cold Ferment)"}],["meta",{"property":"og:description","content":"Rich, soft brioche using early butter incorporation and an overnight cold ferment for structure and flavor."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/brioche-early-butter-cold-ferment.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Brioche (Early Butter, Cold Ferment)"}],["meta",{"name":"twitter:description","content":"Rich, soft brioche using early butter incorporation and an overnight cold ferment for structure and flavor."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/brioche-early-butter-cold-ferment.html"}]]},"headers":[],"relativePath":"recipes/brioche-early-butter-cold-ferment.md","filePath":"recipes/brioche-early-butter-cold-ferment.md"}'),i={name:"recipes/brioche-early-butter-cold-ferment.md"};function o(n,e,s,h,d,c){return r(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="brioche-early-butter-cold-ferment" tabindex="-1">Brioche (Early Butter, Cold Ferment) <a class="header-anchor" href="#brioche-early-butter-cold-ferment" aria-label="Permalink to “Brioche (Early Butter, Cold Ferment)”">​</a></h1><p>This is a rich brioche that leans on an early butter emulsion and a cold ferment to build structure without aggressive kneading. The dough should look sticky and slack early. That is expected. Use the <a href="https://kitchenratio.com/calculator/bread/brioche/" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch.</p><div class="recipe-glance"><div class="recipe-glance-card"><strong>Style</strong><span>Rich brioche with early butter incorporation and a shreddable crumb.</span></div><div class="recipe-glance-card"><strong>Yield</strong><span>Example batch targets about 900g dough for one standard 2 lb loaf tin.</span></div><div class="recipe-glance-card"><strong>Best For</strong><span>Soft sandwich loaves, toast, French toast, and other rich bread applications.</span></div></div><div class="info custom-block"><p class="custom-block-title">Testing Status</p><p>This formula is still being tested and refined.</p></div><h2 id="baker-s" tabindex="-1">Baker&#39;s % <a class="header-anchor" href="#baker-s" aria-label="Permalink to “Baker&#39;s %”">​</a></h2><ul><li><strong>Flour (bread flour)</strong> - 100%</li><li><strong>Whole eggs</strong> - 60-65%</li><li><strong>Milk (for active dry yeast hydration)</strong> - 6-8%</li><li><strong>Unsalted butter, very soft</strong> - 40-45%</li><li><strong>Sugar</strong> - 10-12%</li><li><strong>Salt</strong> - 2%</li><li><strong>Active dry yeast</strong> - 2%</li></ul><h2 id="ingredients-example-batch-1-x-2-lb-loaf-tin" tabindex="-1">Ingredients (Example Batch: 1 x 2 lb loaf tin) <a class="header-anchor" href="#ingredients-example-batch-1-x-2-lb-loaf-tin" aria-label="Permalink to “Ingredients (Example Batch: 1 x 2 lb loaf tin)”">​</a></h2><ul><li><strong>Bread flour</strong> - 400g (100%)</li><li><strong>Whole eggs</strong> - 250g (62.5%)</li><li><strong>Unsalted butter, very soft</strong> - 170g (42.5%)</li><li><strong>Sugar</strong> - 44g (11%)</li><li><strong>Salt</strong> - 8g (2%)</li><li><strong>Active dry yeast</strong> - 8g (2%)</li><li><strong>Milk (for yeast bloom, ~100F / 38C)</strong> - 28g (7%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This batch targets about <strong>900g total dough</strong>, a solid fit for a standard 2 lb loaf tin.</p></div><h2 id="full-size-batch-reference-your-recent-bake" tabindex="-1">Full-Size Batch Reference (Your Recent Bake) <a class="header-anchor" href="#full-size-batch-reference-your-recent-bake" aria-label="Permalink to “Full-Size Batch Reference (Your Recent Bake)”">​</a></h2><ul><li><strong>Bread flour</strong> - 550g</li><li><strong>Whole eggs</strong> - ~350g (about 7 large eggs)</li><li><strong>Unsalted butter</strong> - 226g (2 sticks)</li><li><strong>Sugar</strong> - 55-65g</li><li><strong>Salt</strong> - 11g</li><li><strong>Active dry yeast</strong> - 11g</li><li><strong>Milk (for yeast bloom)</strong> - 30-40g</li></ul><hr><h2 id="procedure-day-1-day-2" tabindex="-1">Procedure (Day 1 -&gt; Day 2) <a class="header-anchor" href="#procedure-day-1-day-2" aria-label="Permalink to “Procedure (Day 1 -&gt; Day 2)”">​</a></h2><h3 id="day-1-mix-and-cold-ferment" tabindex="-1">Day 1 - Mix and Cold Ferment <a class="header-anchor" href="#day-1-mix-and-cold-ferment" aria-label="Permalink to “Day 1 - Mix and Cold Ferment”">​</a></h3><h3 id="_1-bloom-the-yeast" tabindex="-1">1. Bloom the Yeast <a class="header-anchor" href="#_1-bloom-the-yeast" aria-label="Permalink to “1. Bloom the Yeast”">​</a></h3><ul><li>Warm milk to about <strong>100F (38C)</strong>.</li><li>Stir in active dry yeast and a small pinch of sugar.</li><li>Let stand <strong>5-10 minutes</strong> until foamy.</li></ul><h3 id="_2-build-the-early-butter-emulsion" tabindex="-1">2. Build the Early Butter Emulsion <a class="header-anchor" href="#_2-build-the-early-butter-emulsion" aria-label="Permalink to “2. Build the Early Butter Emulsion”">​</a></h3><ul><li>In a large bowl combine: <ul><li>eggs</li><li>sugar</li><li>salt</li><li>bloomed yeast + milk</li><li>all very soft butter</li><li>about <strong>35-40% of the flour</strong></li></ul></li><li>Mix until: <ul><li>butter is fully incorporated</li><li>no visible butter chunks remain</li><li>mixture looks like thick batter</li></ul></li></ul><p>This step builds emulsion first, then gluten.</p><h3 id="_3-add-remaining-flour" tabindex="-1">3. Add Remaining Flour <a class="header-anchor" href="#_3-add-remaining-flour" aria-label="Permalink to “3. Add Remaining Flour”">​</a></h3><ul><li>Add the rest of the flour.</li><li>Mix only until no dry flour remains.</li><li>Do <strong>not</strong> knead aggressively.</li></ul><p>The dough should be sticky, glossy, and slack.</p><h3 id="_4-rest" tabindex="-1">4. Rest <a class="header-anchor" href="#_4-rest" aria-label="Permalink to “4. Rest”">​</a></h3><ul><li>Cover and rest <strong>20-30 minutes</strong> at room temperature.</li><li>Optional: perform one gentle fold with wet hands.</li></ul><h3 id="_5-cold-ferment" tabindex="-1">5. Cold Ferment <a class="header-anchor" href="#_5-cold-ferment" aria-label="Permalink to “5. Cold Ferment”">​</a></h3><ul><li>Cover tightly.</li><li>Refrigerate <strong>12-24 hours</strong>.</li></ul><p>This cold phase is where strength and handling improve.</p><h3 id="day-2-shape-proof-bake" tabindex="-1">Day 2 - Shape, Proof, Bake <a class="header-anchor" href="#day-2-shape-proof-bake" aria-label="Permalink to “Day 2 - Shape, Proof, Bake”">​</a></h3><h3 id="_6-shape-cold-do-not-warm-first" tabindex="-1">6. Shape Cold (Do Not Warm First) <a class="header-anchor" href="#_6-shape-cold-do-not-warm-first" aria-label="Permalink to “6. Shape Cold (Do Not Warm First)”">​</a></h3><ul><li>Turn dough out while still cold.</li><li>Gently flatten and pre-shape into a loose log.</li><li>Rest <strong>10-15 minutes</strong>.</li><li>Flatten slightly into a rectangle, then roll from the short side into a tight log.</li><li>Build gentle surface tension and seal seam.</li><li>Place seam-side down in a greased loaf pan.</li></ul><h3 id="_7-final-proof" tabindex="-1">7. Final Proof <a class="header-anchor" href="#_7-final-proof" aria-label="Permalink to “7. Final Proof”">​</a></h3><ul><li>Cover loosely (an inverted bowl works well).</li><li>Proof at <strong>70-75F (21-24C)</strong> for <strong>2-3 hours</strong>.</li></ul><p>Ready cues:</p><ul><li>dough domes about <strong>3/4 to 1 inch</strong> above pan rim</li><li>surface is smooth and slightly jiggly</li><li>finger poke springs back slowly</li></ul><h3 id="_8-egg-wash" tabindex="-1">8. Egg Wash <a class="header-anchor" href="#_8-egg-wash" aria-label="Permalink to “8. Egg Wash”">​</a></h3><ul><li>Beat 1 whole egg.</li><li>Brush lightly on top only, right before baking.</li></ul><h3 id="_9-bake" tabindex="-1">9. Bake <a class="header-anchor" href="#_9-bake" aria-label="Permalink to “9. Bake”">​</a></h3><ul><li>Bake at <strong>350F (175C)</strong> for <strong>35-45 minutes</strong>.</li><li>Tent loosely with foil if browning too early.</li><li>Internal temperature target: <strong>190-195F (88-91C)</strong>.</li></ul><h3 id="_10-cool" tabindex="-1">10. Cool <a class="header-anchor" href="#_10-cool" aria-label="Permalink to “10. Cool”">​</a></h3><ul><li>Rest <strong>10 minutes</strong> in pan.</li><li>Turn out and cool <strong>45-60 minutes</strong> before slicing.</li></ul><h2 id="what-to-expect" tabindex="-1">What to Expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to “What to Expect”">​</a></h2><ul><li>Very soft loaf</li><li>Shreddable crumb</li><li>Rich yellow interior</li><li>Slightly custardy but fully baked center</li></ul><p>Great for:</p><ul><li>toast</li><li>French toast</li><li>cinnamon rolls</li><li>sandwiches</li></ul><h2 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to “Important Notes”">​</a></h2><ul><li>Sticky dough is correct for this formula.</li><li>Shape cold, then proof warm.</li><li>Do not wait for dramatic doubling in pan.</li><li>For rich dough, internal temperature is more reliable than crust color.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Alternate butter incorporation (mixer method): you can develop dough first with eggs/liquid/flour/salt/yeast, then add very soft butter gradually in a stand mixer until fully absorbed and smooth. This is the classic method and can give a tighter, more uniform structure.</p></div><p>Need a mixer? <a href="https://amzn.to/44EYHO4" target="_blank" rel="noreferrer">KitchenAid Stand Mixer</a>.</p><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/enrichment.html">Enrichment</a></li><li><a href="/guides/fermentation.html">Fermentation</a></li><li><a href="/guides/proofing.html">Proofing</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div><hr><blockquote><p><strong>Affiliate Disclaimer</strong><br> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',55)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
